// Program content is a static snapshot of the existing golf program, not account data.
const tpData=__PROGRAM_DATA__;
Object.assign(state,{trainView:'today',programFive:true});
const tpDate=iso=>new Date(iso+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
const tpViews=['today','week','program','history'];
const tpNav=()=>`<nav class="tp-nav" aria-label="Training views">${tpViews.map(v=>`<button type="button" data-tp-view="${v}" aria-pressed="${state.trainView===v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</nav>`;
function tpProgram(){return `<div class="tp-intro"><div class="h-eyebrow">September 2026 → Spring 2027</div><h1 class="h-title">Your season,<br><em>taking shape.</em></h1></div><section class="tp-now"><div class="h-eyebrow">Now · Phase 1 of 7</div><h2>Establish technique<br>and baseline.</h2><p class="h-body">Build the foundation for the work ahead.</p><div class="h-row"><span class="h-small">${tpDate(tpData.start)} – Sep 30</span><span class="h-small">${state.programFive?'5':'4'} sessions / week</span></div></section><div class="tp-section-title"><h2>The road to your season.</h2></div><div class="tp-journey">${tpData.phases.map((p,i)=>`<details class="tp-phase" ${i===0?'open':''}><summary><span><strong>${p.name}</strong><small>${tpDate(p.start)} – ${tpDate(p.end)}${i===0?' · Current phase':''}</small></span>${I('plus')}</summary><p><b>Strength</b>${p.notes}</p><p><b>Running</b>${p.run_note}</p></details>`).join('')}</div><div class="tp-section-title"><h2>Room to recover.</h2></div><p class="h-body">Lighter weeks are part of the program.</p><div class="tp-dates">${tpData.lighter_weeks.map((d,i)=>`<span class="${i===0?'tp-next-date':''}">${tpDate(d)}${i===0?' · next':''}</span>`).join('')}</div><p class="tp-note">Sets down a third to a half. RPE 6–7, power halved, running easy. Resume from the previous load afterward.</p><div class="tp-section-title"><h2>Tournaments & rounds.</h2></div>${button('First event · '+tpDate(tpData.first_event)+' '+I('arrow-up-right'),'tp-event','h-goal')}<p class="tp-note">Planning date · no tournament added in this preview.</p><div class="tp-section-title"><h2>The five sessions.</h2></div>${Object.entries(tpData.sessions).map(([id,s])=>`<button type="button" class="tp-session" data-act="tp-session-${id}"><span>${id.slice(1).padStart(2,'0')}</span><span>${s.title}<small>${s.target_minutes[0]}–${s.target_minutes[1]} min${id==='S5'?(state.programFive?' · Included':' · Optional, off'):''}</small></span>${I('chevron-right')}</button>`).join('')}<label class="tp-switch">Include Session 5 · easy cardio<input type="checkbox" data-tp-five ${state.programFive?'checked':''}></label><p class="tp-note">70-minute cap. No medicine-ball throws or tosses. Progress within each phase’s rep range.</p><div class="tp-section-title"><h2>Mobility, every day.</h2><span class="h-small">~8 min</span></div>${button('Your daily sequence '+I('arrow-up-right'),'tp-mobility','h-goal')}${button('View this week’s log '+I('arrow-up-right'),'tp-log','h-quiet h-full')}<p class="tp-note">Program preview · current plan structure, sample activity.</p>`}
function tpWeek(){const ids=['S1','S2',null,'S3',state.programFive?'S5':null,'S4',null];return `<h1 class="h-title">A week<br><em>that fits.</em></h1><p class="h-body">September 7–13 · Baseline</p>${ids.map((id,i)=>`<div class="tp-week-row"><time>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}<br>${7+i}</time><div>${id?tpData.sessions[id].title:'Recovery & mobility'}<small>${id?id+' · '+tpData.sessions[id].target_minutes.join('–')+' min':'Daily mobility · ~8 min'}</small></div>${button(I('arrow-up-right'),id?'tp-session-'+id:'tp-mobility','h-icon','aria-label="View '+['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]+' plan"')}</div>`).join('')}<p class="tp-note">Sample rotation · room for travel, golf, and recovery.</p>`}
function tpHistory(){return `<h1 class="h-title">Work done.<br><em>Progress kept.</em></h1><p class="h-body">Recent sessions · sample history</p>${[['Sep 7','Strength session','42 min'],['Sep 8','Easy run','30 min'],['Sep 9','Mobility','12 min']].map(([date,name,dose])=>`<div class="tp-week-row"><time>${date}</time><div>${name}<small>${dose}</small></div>${I('check')}</div>`).join('')}${button('View this week’s log','tp-log','h-quiet h-full')}`}
const priorTrain=train;
train=function(){if(state.session)return priorTrain();const header=top('Train · Golf performance');if(state.trainView==='today')return priorTrain().replace(header,header+tpNav()).replace('Today · Foundation, week 3','Today · Baseline, week 1').replace('This week · Foundation','This week · Baseline');return header+tpNav()+(state.trainView==='program'?tpProgram():state.trainView==='week'?tpWeek():tpHistory())};
const beforeProgramAct=act;
act=function(a){
 if(a==='program'||a==='training-history'){closeSheet();state.tab='train';state.trainView=a==='program'?'program':'history';render();touchCue('Selection tick',state.trainView);return}
 if(a==='program-train'){state.trainView='today';return beforeProgramAct(a)}
 if(a==='tp-event'){openSheet('Ready when it matters.',`<p class="h-body">First-event planning date · ${tpDate(tpData.first_event)}, 2027</p><div class="h-detail-row"><span>Pre-event phase begins</span><span>${tpDate(tpData.phases.find(p=>p.key==='pre_event').start)}</span></div><p class="h-body">Your earliest tournament sets the five-week lead-in. Tournament weeks use the taper template.</p><p class="tp-note">Planning date only · no tournament recorded.</p>`);return}
 if(a==='tp-mobility'){openSheet('A little mobility, daily.',`<p class="h-body">About eight minutes.</p>${tpData.mobility.map(([name,dose])=>`<div class="h-detail-row"><span>${name}</span><span>${dose}</span></div>`).join('')}`);return}
 if(a==='tp-log'){openSheet('This week, recorded.',`<p class="h-body">September 7–13 · sample log</p><div class="tp-log">Mon · Strength session · 42 min\nTue · Easy run · 30 min\nWed · Mobility · 12 min\nThu · Planned session</div><p class="tp-note">Sample sessions · September 7–13</p>`);return}
 if(a.startsWith('tp-session-')){const id=a.slice(11),s=tpData.sessions[id];if(!s)return;openSheet(id+' · '+s.title,`<p class="h-body">${s.target_minutes.join('–')} minutes</p><p class="tp-note">${s.budget}</p>${s.warmup.length?'<div class="tp-section-title"><h2>Warm-up</h2></div>'+s.warmup.map(w=>`<p class="tp-note">${w}</p>`).join(''):''}${s.blocks.map(b=>`<div class="tp-section-title"><h2>${b.name}</h2><span class="h-small">${b.minutes} min</span></div>${b.exercises.map(e=>`<div class="h-detail-row"><span>${e.name}</span><span>${e.sets} × ${e.reps}${e.per_side?' / side':''}</span></div>`).join('')}`).join('')}${s.run?`<div class="tp-section-title"><h2>Running</h2></div><p class="h-body">${s.run.structure}</p>`:''}<p class="tp-note">Reference template. Today’s phase, recovery, and time budget determine the prescribed dose.</p>`);return}
 return beforeProgramAct(a)
};
root.addEventListener('click',e=>{const b=e.target.closest('[data-tp-view]');if(!b||performance.now()<suppressUntil)return;state.trainView=b.dataset.tpView;render(false);touchCue('Selection tick',b.textContent)});
root.addEventListener('change',e=>{if(!e.target.matches('[data-tp-five]'))return;state.programFive=e.target.checked;render(false);root.querySelector('[data-tp-five]')?.focus();touchCue('Light impact','Weekly session preference updated')});
